// Lo envía el CRM (Enviar Dossier VIP) con la selección de inmuebles para el cliente.
// ===== CONFIGURA AQUÍ =====
const URL_LOGO = 'https://maximusinmobiliaria.tech/assets/email/logo-maximus-email.png';
const URL_CATALOGO = 'https://maximusinmobiliaria.tech/catalog.html';
const WHATSAPP_OFICINA = '584247835697';
// ==========================
const b = $input.first().json.body || $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const aWa = (t) => { const d = String(t || '').replace(/\D/g, ''); if (!d) return ''; if (d.startsWith('58')) return d; return '58' + d.replace(/^0/, ''); };
const urlSegura = (u) => /^https?:\/\//i.test(String(u || '')) ? esc(u) : '';

const objetos = (a) => Array.isArray(a) ? a.filter(x => x && typeof x === 'object') : [];
let lista = objetos(b.inmuebles_detalle);
if (!lista.length) lista = objetos(b.inmuebles);

const cliente = String(b.cliente || b.cliente_nombre || 'Cliente').trim();
const email = String(b.cliente_email || b.email || '').trim();
const asesor = String(b.asesor || b.asesor_nombre || 'Asesor MAXIMUS').trim();
const telAsesor = aWa(b.asesor_telefono) || WHATSAPP_OFICINA;
const titulo = String(b.titulo || 'Portafolio Exclusivo MAXIMUS').trim();
const nota = String(b.nota || '').trim();

const precioTxt = (p) => {
  const s = String(p == null ? '' : p).trim();
  if (!s) return 'Consultar';
  return /^\d+(\.\d+)?\s*(USD)?$/i.test(s) ? 'US$ ' + Number(s.replace(/[^\d.]/g, '')).toLocaleString('en-US') : s.replace(/\s*USD$/i, '').replace(/^/, 'US$ ');
};

const tarjetas = lista.slice(0, 8).map(p => {
  const foto = urlSegura(p.foto);
  const datos = [p.habitaciones ? esc(p.habitaciones) + ' hab.' : '', p.banos ? esc(p.banos) + ' baños' : '', p.m2 ? esc(p.m2) + ' m²' : ''].filter(Boolean).join(' · ');
  return '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #E2E8F0;border-radius:14px;overflow:hidden;margin:0 0 14px 0;background:#FFFFFF;">'
    + (foto ? '<tr><td><img src="' + foto + '" width="528" alt="" style="display:block;width:100%;height:auto;max-height:230px;object-fit:cover;border:0;"></td></tr>' : '')
    + '<tr><td style="padding:14px 18px;">'
    + '<p style="margin:0 0 4px 0;font-size:10px;font-weight:800;letter-spacing:1.5px;color:#059669;text-transform:uppercase;">' + esc(p.codigo || '#MAX') + '</p>'
    + '<p style="margin:0 0 6px 0;font-size:15px;font-weight:800;color:#0F172A;line-height:1.35;">' + esc(p.titulo || 'Inmueble MAXIMUS') + '</p>'
    + '<p style="margin:0 0 6px 0;font-size:17px;font-weight:800;color:#0B4A3F;">' + esc(precioTxt(p.precio)) + '</p>'
    + (p.ubicacion ? '<p style="margin:0 0 4px 0;font-size:12px;color:#64748B;">📍 ' + esc(p.ubicacion) + '</p>' : '')
    + (datos ? '<p style="margin:0;font-size:12px;color:#475569;">' + datos + '</p>' : '')
    + '</td></tr></table>';
}).join('');

return [{ json: {
  cliente: esc(cliente), primer_nombre: esc(cliente.split(/\s+/)[0]), email,
  tiene_email: /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email),
  titulo: esc(titulo), nota: esc(nota), asesor: esc(asesor),
  asesor_email: String(b.asesor_email || '').trim(),
  cantidad: lista.length,
  propiedades_html: tarjetas || '<p style="margin:0 0 18px 0;font-size:14px;color:#475569;line-height:1.6;">Tu asesor te compartirá la selección de inmuebles en los próximos minutos. Mientras tanto, puedes ver todo nuestro catálogo.</p>',
  url_catalogo: URL_CATALOGO, logo_url: URL_LOGO,
  url_whatsapp_asesor: 'https://wa.me/' + telAsesor,
} }];
